// Ships no declarations, like the traced node_modules of a Next.js
// standalone build. Records the environment its evaluation saw.
const seenMode = process.env.ISLAND_MODE;
const seenConfig = process.env.ISLAND_CONFIG;
globalThis.__envkitLoads = (globalThis.__envkitLoads || 0) + 1;
exports.seen = () => `envkit saw ISLAND_MODE=${seenMode}, config=${seenConfig}`;
exports.loads = () => globalThis.__envkitLoads;
